n=22
G=[[4]*n for _ in range(n)]
objs=[(3,0,8,6),(5,17,2,1),(9,12,2,9),(12,5,8,7),(16,0,8,2),(17,17,2,6)]
for r,c,bg,fg in objs:
    for i in range(5):
        for j in range(5):
            v=fg if 1<=i<=3 and 1<=j<=3 else bg
            if G[r+i][c+j] != 4:
                print('collision',r+i,c+j,G[r+i][c+j],v)
            G[r+i][c+j]=v
print('\n'.join(' '.join(map(str,row)) for row in G))
